def calculate_total(items, discount_threshold=1000):
    subtotal = sum(item['price'] * item['qty'] for item in items)
    discount = 0
    if subtotal > discount_threshold:
        discount = subtotal * 0.1
    return subtotal - discount


def apply_discount(amount):
    if amount < 1000:
        return amount * 0.9
    return amount
